import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import { t } from '../util';
/**
 * A #fragment link: "#" (a placeholder while a site is being built) does
 * nothing, and "#id" scrolls to that element when the page has one. Neither
 * touches the address bar, so Flarum's router never sees a navigation.
 */
function jump(e, url) {
  e.preventDefault();
  const target = url.length > 1 ? document.getElementById(decodeURIComponent(url.slice(1))) : null;
  target?.scrollIntoView({
    behavior: 'smooth',
    block: 'start'
  });
}

/** The footer: the forum's name, the admin's links and "Powered by Flarum". */
export default class MastheadFooter extends Component {
  view() {
    const links = app.forum.attribute('mastheadFooterLinks') || [];
    const base = app.forum.attribute('baseUrl');
    return m("div", {
      className: "MastheadFooter"
    }, m("div", {
      className: "container MastheadFooter-inner"
    }, m("span", {
      className: "MastheadFooter-name"
    }, app.forum.attribute('title')), links.length ? m("nav", {
      className: "MastheadFooter-links",
      "aria-label": t('footer.label')
    }, links.map(link => {
      // The server already refused anything but a path, http(s),
      // mailto or a #fragment. Off-site links open in a new tab, and
      // are told not to hand this page to the one they open.
      if (link.url.startsWith('#')) {
        return m("a", {
          href: link.url,
          onclick: e => jump(e, link.url)
        }, link.label);
      }
      const external = !link.url.startsWith('/') && !link.url.startsWith(base);
      return m("a", Object.assign({
        href: link.url
      }, external ? {
        target: '_blank',
        rel: 'noopener noreferrer'
      } : {}), link.label);
    })) : null, app.forum.attribute('mastheadPoweredBy') ? m("a", {
      className: "MastheadFooter-powered",
      href: "https://flarum.org",
      target: "_blank",
      rel: "noopener noreferrer"
    }, t('footer.powered_by')) : null));
  }
}
flarum.reg.add('ernestdefoe-masthead', 'forum/components/MastheadFooter', MastheadFooter);